# Re-run everything in one block
from itertools import combinations
from z3 import *
from collections import deque

n = 21
edges = {}
for i in range(n):
    for j in range(i+1, n):
        edges[(i,j)] = Bool(f'e_{i}_{j}')

s = Solver()

for v in range(n):
    neighbors = []
    for u in range(n):
        if u != v:
            key = (min(u,v), max(u,v))
            neighbors.append(edges[key])
    s.add(Sum([If(e, 1, 0) for e in neighbors]) >= 4)
    s.add(Sum([If(e, 1, 0) for e in neighbors]) <= 6)

for i, j, k in combinations(range(n), 3):
    s.add(Not(And(edges[(i,j)], edges[(i,k)], edges[(j,k)])))

for i in range(n):
    for j in range(i+1, n):
        others = [v for v in range(n) if v != i and v != j]
        for k, l in combinations(others, 2):
            ik = edges[(min(i,k), max(i,k))]
            jk = edges[(min(j,k), max(j,k))]
            il = edges[(min(i,l), max(i,l))]
            jl = edges[(min(j,l), max(j,l))]
            s.add(Not(And(ik, jk, il, jl)))

print("Solving...")
result = s.check()
print(f"Result: {result}")

if result == sat:
    m = s.model()
    edge_list = []
    for (i,j), var in edges.items():
        if is_true(m[var]):
            edge_list.append((i,j))

    print(f"Number of edges: {len(edge_list)}")

    degrees = [0] * n
    adj = {v: set() for v in range(n)}
    for (u,v) in edge_list:
        degrees[u] += 1
        degrees[v] += 1
        adj[u].add(v)
        adj[v].add(u)

    print(f"Degrees: {degrees}")
    print(f"Min degree: {min(degrees)}, Max degree: {max(degrees)}")

    triangles = sum(1 for i,j,k in combinations(range(n),3)
                    if j in adj[i] and k in adj[i] and k in adj[j])
    print(f"Triangles: {triangles}")

    bad_pairs = sum(1 for i in range(n) for j in range(i+1,n)
                    if len(adj[i] & adj[j]) >= 2)
    print(f"Pairs with 2+ common neighbors: {bad_pairs}")

    def bfs_girth(start):
        dist = [-1] * n
        dist[start] = 0
        parent = [-1] * n
        queue = deque([start])
        min_cycle = float('inf')
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif parent[u] != v:
                    cycle_len = dist[u] + dist[v] + 1
                    min_cycle = min(min_cycle, cycle_len)
        return min_cycle

    girth = min(bfs_girth(v) for v in range(n))
    print(f"Girth: {girth}")
    print("\nEdge list:")
    for e in sorted(edge_list):
        print(e)
